"use strict";
let midayReady=false,midaySyncTimer,midaySearchTimer,midaySyncing=false,midayLastSync='',midayRequest=0,midayRows=[],midayHasMore=false,midayOffset=0,midayPlanet='',midaySyncError='',midayInitialising=false,midaySharingBusy=false,midayConnectAttempts=0;
function midayPreferences(){state.userSettings.shareScansToAll=!!state.userSettings.shareScansToAll;state.midayTypes={...Object.fromEntries(SCAN_TYPES.map(([id])=>[id,true])),...(state.midayTypes||{})};state.midaySearch=state.midaySearch||'';}
function midayScanIcon(type){return waveScanIcon(type).replace(/ data-scan="[^"]*"/g,'');}
async function midayAPI(path,options={}){const response=await fetch('/api/miday/'+path,{credentials:'same-origin',...options,headers:{'Content-Type':'application/json',...(options.headers||{})}});let data;try{data=await response.json();}catch{throw Error('The central scan database is unavailable.');}if(!response.ok)throw Error(data.error||'Could not contact the central scan database.');return data;}
function refreshSharingControl(){const retry=document.getElementById('scanSharingRetry');if(retry)retry.hidden=midayReady||midayInitialising;const input=document.getElementById('shareScansToAll');if(input){input.checked=!!state.userSettings.shareScansToAll;input.disabled=!midayReady||midaySharingBusy;}const status=document.getElementById('scanSharingStatus');if(status)status.textContent=midaySyncError||(!midayReady?'Connecting to the central database…':state.userSettings.shareScansToAll?'Your stored scans are visible to all visitors of this site.':'Your scans are stored centrally and remain private.');}
async function initializeMiday(){if(midayInitialising)return;midayInitialising=true;midayConnectAttempts++;midayPreferences();try{const result=await midayAPI('sharing');state.userSettings.shareScansToAll=result.enabled;midayReady=true;midaySyncError='';save();await syncCentralScans();}catch(error){midayReady=false;midaySyncError=error.message+' · Retry the scan connection.';if(midayConnectAttempts<3)setTimeout(initializeMiday,1000*midayConnectAttempts);}finally{midayInitialising=false;refreshSharingControl();}}

function queueCentralScanSync(){if(!midayReady)return;clearTimeout(midaySyncTimer);midaySyncTimer=setTimeout(()=>syncCentralScans(),250);}
async function syncCentralScans(){
  if(!midayReady||midaySyncing||(typeof planetDirectoryReady!=='undefined'&&!planetDirectoryReady))return;
  const cutoff=Date.now()-14*24*60*60*1000;
  const scans=state.waves.scans.filter(sc=>!sc.savedAt||sc.savedAt>cutoff).map(sc=>({...sc,savedAt:sc.savedAt||Date.now()}));
  for(const sc of scans){const local=state.waves.scans.find(x=>x.id===sc.id);if(local&&!local.savedAt)local.savedAt=sc.savedAt;}
  const signature=JSON.stringify(scans),sourceVersion=JSON.stringify(state.waves.scans);if(signature===midayLastSync)return;
  midaySyncing=true;try{for(let offset=0;offset<scans.length;offset+=100)await midayAPI('scans',{method:'POST',body:JSON.stringify({scans:scans.slice(offset,offset+100),resetGeneration:state.centralResetGeneration||0})});midayLastSync=signature;midaySyncError='';if(document.getElementById('page-miday')?.classList.contains('active'))await loadMidayScans();}catch(error){midaySyncError=error.message;}finally{midaySyncing=false;refreshSharingControl();if(sourceVersion!==JSON.stringify(state.waves.scans))queueCentralScanSync();}
}
async function setSharingToAll(enabled){
  if(!midayReady||midaySharingBusy)return;
  midaySharingBusy=true;
  const input=document.getElementById('shareScansToAll');if(input)input.disabled=true;
  try{const result=await midayAPI('sharing',{method:'POST',body:JSON.stringify({enabled})});state.userSettings.shareScansToAll=result.enabled;midaySyncError='';save();await syncCentralScans();notify(enabled?'Scan sharing enabled for all site visitors.':'Your scans are now private.');if(document.getElementById('page-miday')?.classList.contains('active'))await loadMidayScans();}catch(error){midaySyncError=error.message;notify(error.message,true);}finally{midaySharingBusy=false;refreshSharingControl();}
}
function buildMidayPage(){const root=document.getElementById('midayContent');if(!root)return;midayPreferences();root.innerHTML=testBattleUplinkHTML()+'<section class="panel"><div class="ph"><div class="pt">THE MIDAY ARRAY</div><span class="meta">CENTRAL SCAN DATABASE</span></div><div class="news-controls"><div class="news-filter-head"><label class="news-filter-chip news-filter-all"><input type="checkbox" id="midayAllTypes"> All scan types</label><span id="midayCount" class="meta" role="status">Loading scans…</span></div><div class="news-category-filters">'+SCAN_TYPES.map(([id,name])=>'<label class="news-filter-chip miday-type-filter">'+midayScanIcon(id)+'<input type="checkbox" data-miday-type="'+id+'" '+(state.midayTypes[id]?'checked':'')+'>'+esc(name)+'</label>').join('')+'</div><div class="field news-search-field"><label for="midaySearch">Search scans</label><input type="search" id="midaySearch" placeholder="Planet, coordinates, scan type or report text"></div><div id="midayPlanetFilter" class="miday-planet-filter"></div><div class="copy-actions"><button class="btn" data-miday-refresh>REFRESH SCANS</button></div></div><div id="midayReports" aria-live="polite"></div><div class="controls"><button class="btn" id="midayMore" data-miday-more hidden>LOAD MORE SCANS</button></div></section><p class="settings-hint">Scans shared by players are stored in the central database for two weeks. Only players who enable sharing appear here. The site’s existing access rules apply.</p>';document.getElementById('midaySearch').value=state.midaySearch;updateMidayFilters();}
function updateMidayFilters(){const master=document.getElementById('midayAllTypes');if(master){const count=SCAN_TYPES.filter(([id])=>state.midayTypes[id]).length;master.checked=count===SCAN_TYPES.length;master.indeterminate=count>0&&count<SCAN_TYPES.length;}const planet=document.getElementById('midayPlanetFilter');if(planet)planet.innerHTML=midayPlanet?'Planet: <b>'+esc(midayPlanet)+'</b> <button class="btn" data-miday-clear-planet>CLEAR PLANET FILTER</button>':'';}
function renderMidayReports(){const el=document.getElementById('midayReports');if(!el)return;el.innerHTML=midayRows.length?midayRows.map(sc=>'<article class="miday-report">'+midayScanIcon(sc.type)+'<div><h3>'+esc(sc.name||sc.type)+' · '+esc(sc.targetName)+'</h3><p class="meta">'+(sc.anonymous?'COORDINATES HIDDEN':esc(sc.coords))+' · TICK '+sc.tick+' · '+esc(new Date(sc.savedAt).toLocaleString())+'</p><pre>'+esc(typeof readableScanText==='function'?readableScanText(sc.text):sc.text)+'</pre></div></article>').join(''):'<div class="news-empty">No shared scans match these filters.</div>';document.getElementById('midayCount').textContent=midayRows.length+' SCANS'+(midayHasMore?' · MORE AVAILABLE':'');document.getElementById('midayMore').hidden=!midayHasMore;}
async function loadMidayScans(append=false){
  const id=++midayRequest,enabled=SCAN_TYPES.filter(([type])=>state.midayTypes[type]).map(([type])=>type);updateMidayFilters();
  if(!enabled.length){midayRows=[];midayHasMore=false;renderMidayReports();return;}
  if(!append){midayRows=[];midayOffset=0;document.getElementById('midayCount').textContent='Loading scans…';}
  const params=new URLSearchParams({q:state.midaySearch,offset:String(append?midayOffset:0)});for(const type of enabled)params.append('type',type);if(midayPlanet)params.set('coords',midayPlanet);
  try{const data=await midayAPI('scans?'+params);if(id!==midayRequest)return;midayRows=append?[...midayRows,...data.scans]:data.scans;midayHasMore=data.hasMore;midayOffset=data.nextOffset;renderMidayReports();}catch(error){if(id!==midayRequest)return;document.getElementById('midayCount').textContent='DATABASE UNAVAILABLE';document.getElementById('midayReports').innerHTML='<div class="news-empty">'+esc(error.message)+' Use Refresh Scans to try again.</div>';document.getElementById('midayMore').hidden=true;}
}
function openMidayForPlanet(coords){midayPlanet=coords;state.midaySearch='';state.midayTypes=Object.fromEntries(SCAN_TYPES.map(([id])=>[id,true]));save();navigate('miday');}
document.addEventListener('change',e=>{if(e.target.id==='shareScansToAll')setSharingToAll(e.target.checked);if(e.target.id==='midayAllTypes'){state.midayTypes=Object.fromEntries(SCAN_TYPES.map(([id])=>[id,e.target.checked]));document.querySelectorAll('[data-miday-type]').forEach(input=>input.checked=e.target.checked);save();loadMidayScans();}if(e.target.matches('[data-miday-type]')){state.midayTypes[e.target.dataset.midayType]=e.target.checked;save();loadMidayScans();}});
document.addEventListener('input',e=>{if(e.target.id==='midaySearch'){state.midaySearch=e.target.value;save();clearTimeout(midaySearchTimer);midaySearchTimer=setTimeout(()=>loadMidayScans(),250);}});
document.addEventListener('click',e=>{const planet=e.target.closest('[data-planet-scans]');if(planet)openMidayForPlanet(planet.dataset.planetScans);const menu=e.target.closest('[data-page="miday"]');if(menu){midayPlanet='';loadMidayScans();}const deleted=e.target.closest('[data-deletescan]');if(deleted&&midayReady)midayAPI('scans',{method:'DELETE',body:JSON.stringify({ids:[deleted.dataset.deletescan]})}).then(()=>{if(document.getElementById('page-miday')?.classList.contains('active'))loadMidayScans();}).catch(error=>notify(error.message,true));if(e.target.closest('[data-miday-refresh]'))initializeMiday().then(()=>loadMidayScans());if(e.target.closest('[data-miday-more]'))loadMidayScans(true);if(e.target.closest('[data-miday-clear-planet]')){midayPlanet='';loadMidayScans();}});
midayPreferences();initializeMiday();

fetch('/api/portal/session',{credentials:'same-origin'}).then(r=>r.json()).then(data=>{window.staffPermissionNodes=data.user?.staffPermissions||{};window.isGameAdmin=staffCan('adminControl');renderAlliance();}).catch(()=>{});

document.addEventListener('click',e=>{if(e.target.closest('[data-miday-connect]')){midayConnectAttempts=0;initializeMiday();}});
